#include <print>
#include <algorithm>
#include <vector>

int main() {
    std::vector<int> a = {1, 2, 3, 4};
    int n = 0;
    do {
        ++n;
        for (int v : a) std::print("{} ", v);
        std::println("");
    } while (std::next_permutation(a.begin(), a.end()));
    std::println("一共 {} 个排列", n);
    std::vector<int> b = {3, 2, 1};
    int m = 0;
    do {
        ++m;
        for (int v : b) std::print("{} ", v);
        std::println("");
    } while (std::next_permutation(b.begin(), b.end()));
    std::println("跑了 {} 轮", m);
    // 只打了一行 3 2 1，收尾时 b 被重排回 1 2 3
    return 0;
}

